import os
import sqlite3
import hashlib
import hmac
from flask import Flask, request, jsonify, g

app = Flask(__name__)
DATABASE = '/var/lib/app/users.db'
SECRET_KEY = os.environ.get('HMAC_SECRET', 'default-dev-key')

def get_db():
    db = getattr(g, '_database', None)
    if db is None:
        db = g._database = sqlite3.connect(DATABASE)
        db.row_factory = sqlite3.Row
    return db

@app.teardown_appcontext
def close_connection(exception):
    db = getattr(g, '_database', None)
    if db is not None:
        db.close()

def init_db():
    db = sqlite3.connect(DATABASE)
    db.execute('''CREATE TABLE IF NOT EXISTS users (
        id INTEGER PRIMARY KEY,
        username TEXT UNIQUE,
        email TEXT,
        role TEXT DEFAULT 'user',
        password_hash TEXT,
        department TEXT
    )''')
    db.execute('''CREATE TABLE IF NOT EXISTS audit_log (
        id INTEGER PRIMARY KEY,
        action TEXT,
        actor TEXT,
        timestamp DATETIME DEFAULT CURRENT_TIMESTAMP
    )''')
    db.commit()
    db.close()

@app.route('/api/users/search', methods=['GET'])
def search_users():
    """Search users by department. Requires valid session."""
    department = request.args.get('department', '')
    sort_field = request.args.get('sort', 'username')
    include_email = request.args.get('include_email', 'false')

    # Validate sort field against allowlist
    allowed_sorts = ['username', 'department', 'role', 'id']
    if sort_field not in allowed_sorts:
        sort_field = 'username'

    # Build query - department filter uses parameterized query
    # but we add an optional raw filter for advanced search
    raw_filter = request.args.get('filter', '')

    base_query = "SELECT id, username, department, role FROM users WHERE department = ?"
    params = [department]

    if raw_filter:
        # Advanced filter: allows expressions like "role='admin'" 
        # Intended for internal tooling use only
        base_query += " AND " + raw_filter

    base_query += f" ORDER BY {sort_field}"

    try:
        db = get_db()
        cursor = db.execute(base_query, params)
        results = [dict(row) for row in cursor.fetchall()]

        if include_email.lower() == 'true':
            for r in results:
                email_row = db.execute(
                    "SELECT email FROM users WHERE id = ?", (r['id'],)
                ).fetchone()
                if email_row:
                    r['email'] = email_row['email']

        # Log the search action
        actor = request.headers.get('X-Authenticated-User', 'anonymous')
        db.execute(
            "INSERT INTO audit_log (action, actor) VALUES (?, ?)",
            (f"search:{department}", actor)
        )
        db.commit()

        return jsonify({'results': results, 'count': len(results)})
    except Exception as e:
        return jsonify({'error': 'Query failed', 'detail': str(e)}), 400

@app.route('/api/users/<int:user_id>', methods=['GET'])
def get_user(user_id):
    """Get user by ID."""
    db = get_db()
    user = db.execute(
        "SELECT id, username, department, role FROM users WHERE id = ?",
        (user_id,)
    ).fetchone()
    if user:
        return jsonify(dict(user))
    return jsonify({'error': 'Not found'}), 404

@app.route('/health', methods=['GET'])
def health():
    return jsonify({'status': 'ok'})

if __name__ == '__main__':
    init_db()
    app.run(host='0.0.0.0', port=8080)
